                markers.append((r, c, color))

    # Rays pass through the marker's own 3-arms, then continue through empty
    # cells until another original non-background cell blocks that direction.
    for r, c, color in markers:
        for step in (-1, 1):
            x = c + step
            if 0 <= x < w and src[r][x] == 3:
