{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = []
    blocked_cols = set()

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            arms = ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            if all(src[rr][cc] == 3 for rr, cc in arms):
                if src[r][c] == 0:
                    blocked_cols.add(c)
                elif src[r][c] not in (0, 3):
                    centers.append((r, c, src[r][c]))

    # Extend each colored plus in both directions. Its original arms remain 3;
    # other nonzero input cells stop the ray. Empty-plus columns stay unpainted.
    for r, c, color in centers:
        for step in (-1, 1):
            x = c + step
            if 0 <= x < w and src[r][x] == 3:
                x += step
            while 0 <= x < w and src[r][x] == 0:
                if x not in blocked_cols:
                    out[r][x] = color
                x += step

    # Vertical strokes are drawn after horizontal ones, so they win at crossings.
    for r, c, color in centers:
        if c in blocked_cols:
            continue
        for step in (-1, 1):
            y = r + step
            if 0 <= y < h and src[y][c] == 3:
                y += step
            while 0 <= y < h and src[y][c] == 0:
                out[y][c] = color
                y += step
    return out
