{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = []

    # Colored centers are the nonzero cells with four green arms.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = src[r][c]
            if color not in (0, 3) and all(
                src[rr][cc] == 3
                for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
            ):
                centers.append((r, c, color))

    # Draw horizontal rays first, then vertical rays. Skip each center's own
    # adjacent arm; a green arm belonging to another plus stops the ray.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            if 0 <= x < w and src[r][x] == 3:
                x += dc  # pass through own arm
            while 0 <= x < w:
                if src[r][x] == 3:
                    break
                if src[r][x] == 0:
                    out[r][x] = color
                x += dc

    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            if 0 <= y < h and src[y][c] == 3:
                y += dr  # pass through own arm
            while 0 <= y < h:
                if src[y][c] == 3:
                    break
                if src[y][c] == 0:
                    out[y][c] = color
                y += dr
    return out
