                centers.append((r,c,color))

    # Colored crosses send full row/column strokes. Green-only pluses are
    # dividers: their row/column stays clear of the crossing colored strokes.
    green_only_rows, green_only_cols = set(), set()
    for r in range(1,h-1):
        for c in range(1,w-1):
            if src[r][c] == 0 and all(src[rr][cc] == 3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                green_only_rows.add(r)
