    for r,c,color in centers:
        if r not in green_only_rows:
            for x in range(w):
                if src[r][x] == 0: out[r][x] = color
        if c not in green_only_cols:
            for y in range(h):
                if src[y][c] == 0: out[y][c] = color
    return out
